SELECT

FROM t_post
WHERE status = 1
AND type = #{type}

    AND board_id = #{boardId}


    AND (publish_time, id) < (#{cursorTime}, #{cursorId})

ORDER BY publish_time DESC, id DESC
LIMIT #{size}

SELECT
FROM t_post WHERE status = 1 AND type = 0
AND board_id = #{boardId}
AND (hot_score, id) < (#{cursorScore}, #{cursorId})
ORDER BY hot_score DESC, id DESC LIMIT #{size}

